-- Deploy ff2b_db:courts to pg

BEGIN;

CREATE TABLE IF NOT EXISTS "court_categories" (
    -- Unique identifier of the court category
    "id" SMALLINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    -- Unique code of the court category
    "code" TEXT NOT NULL UNIQUE,
    -- Unique label of the court category
    "label" TEXT NOT NULL UNIQUE,
    -- Description of the court category
    "description" TEXT
);

COMMENT ON COLUMN "court_categories"."id" IS 'Unique identifier of the court category';
COMMENT ON COLUMN "court_categories"."code" IS 'Unique code of the court category';
COMMENT ON COLUMN "court_categories"."label" IS 'Unique label of the court category';
COMMENT ON COLUMN "court_categories"."description" IS 'Description of the court category';

CREATE TABLE IF NOT EXISTS "courts_sizes" (
    -- Unique identifier of the court size
    "id" SMALLINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    -- Unique code of the court size
    "code" TEXT NOT NULL UNIQUE,
    -- Unique label of the court size
    "label" TEXT NOT NULL UNIQUE,
    -- Description of the court size
    "description" TEXT
);

COMMENT ON COLUMN "courts_sizes"."id" IS 'Unique identifier of the court size';
COMMENT ON COLUMN "courts_sizes"."code" IS 'Unique code of the court size';
COMMENT ON COLUMN "courts_sizes"."label" IS 'Unique label of the court size';
COMMENT ON COLUMN "courts_sizes"."description" IS 'Description of the court size';


CREATE TABLE IF NOT EXISTS "courts" (
    -- Unique identifier of the court
    "id" UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    -- The Practice site id the court is associated with
    "practice_site_id" INTEGER NOT NULL,
    -- Name of the court
    "name" TEXT NOT NULL,
    -- A description of the court
    "description" TEXT,
    -- The category of the court referencing court categories table
    "court_category_id" SMALLINT NOT NULL,
    -- The size of the court referencing court_sizes table
    "court_size_id" SMALLINT NOT NULL,

    CONSTRAINT "fk_courts_practice_site_id_practice_sites"
        FOREIGN KEY ("practice_site_id")
        REFERENCES "practice_sites"("id")
        ON DELETE RESTRICT
        ON UPDATE NO ACTION,

    CONSTRAINT "fk_courts_court_category_id_court_categories"
        FOREIGN KEY ("court_category_id")
        REFERENCES "court_categories"("id")
        ON DELETE RESTRICT
        ON UPDATE NO ACTION,
    
    CONSTRAINT "fk_courts_court_size_id_courts_sizes"
        FOREIGN KEY ("court_size_id")
        REFERENCES "courts_sizes"("id")
        ON DELETE RESTRICT
        ON UPDATE NO ACTION,

    CONSTRAINT "unique_courts_practice_site_id_name"
    UNIQUE ("practice_site_id", "name") 
);

COMMENT ON COLUMN "courts"."id" IS 'Unique identifier of the court';
COMMENT ON COLUMN "courts"."practice_site_id" IS 'The identifier of the practice site the court is associated with';
COMMENT ON COLUMN "courts"."name" IS 'The name of the court';
COMMENT ON COLUMN "courts"."description" IS 'The description of the court';
COMMENT ON COLUMN "courts"."court_category_id" IS 'The category of the court referencing court_categories table';

CREATE INDEX "idx_courts_practice_site_id"
    ON "courts" ("practice_site_id");

CREATE INDEX "idx_courts_court_category_id"
    ON "courts" ("court_category_id");

CREATE INDEX "idx_courts_court_size_id"
    ON "courts" ("court_size_id");

COMMIT;
